<?php
require_once __DIR__.'/../../includes/accounting_ui.php';$type=$_GET['type']??'trial';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$student=(int)($_GET['student']??$_GET['student_id']??0);$class=(int)($_GET['class_id']??0);$year=(int)($_GET['academic_year_id']??0);$method=(int)($_GET['method_id']??0);$cashier=(int)($_GET['cashier']??0);$headers=[];$rows=[];$numeric=[];
$types=['trial'=>'Trial balance','income'=>'Income statement / income vs expense','balance'=>'Balance sheet','ledger'=>'General ledger / journals','cash'=>'Cashbook','bank'=>'Bankbook','collection'=>'Daily / monthly / yearly collections','class_collection'=>'Class-wise collections','category'=>'Fee-category collections','dues'=>'Outstanding / defaulters / aging','expenses'=>'Expense report','student'=>'Student ledger','reconciliation'=>'Receivables & advances reconciliation'];
try{
    $from=schoolDateToAd($from)??'';$to=schoolDateToAd($to)??'';if(!$from||!$to||$to<$from||!isset($types[$type]))throw new InvalidArgumentException('Choose a report and ordered dates.');
    if($class)schoolRecord($db,'classes',$class,$school);if($year)schoolRecord($db,'academic_years',$year,$school);if($method)$ac->record('ac_methods',$method);if($cashier)schoolRecord($db,'users',$cashier,$school);
    if(in_array($type,['trial','income','balance'],true)){
        $balances=$ac->balances($type==='income'?$from:'1900-01-01',$to);$headers=['Code','Account','Type','Debit NPR','Credit NPR','Debit - credit NPR'];$numeric=[3,4,5];$dr=0;$cr=0;$surplus=0;
        foreach($balances as $r){$d=(int)$r['debit_minor'];$c=(int)$r['credit_minor'];if(in_array($r['type'],['income','contra_income','expense'],true))$surplus+=$c-$d;if($type==='income'&&!in_array($r['type'],['income','contra_income','expense'],true))continue;if($type==='balance'&&!in_array($r['type'],['asset','liability','equity'],true))continue;$rows[]=[$r['code'],$r['name'],$r['type'],acAmount($d),acAmount($c),acAmount($d-$c)];$dr+=$d;$cr+=$c;}
        if($type==='balance'){$rows[]=['','Accumulated posted surplus / deficit','equity',acAmount(max(0,-$surplus)),acAmount(max(0,$surplus)),acAmount(-$surplus)];$dr+=max(0,-$surplus);$cr+=max(0,$surplus);}
        $rows[]=['','Total','',acAmount($dr),acAmount($cr),acAmount($dr-$cr)];if($type==='income')$rows[]=['','Surplus / deficit','income - expense','','',acAmount($surplus)];
    }elseif(in_array($type,['ledger','cash','bank','student'],true)){
        if($type==='student'&&!$student)throw new InvalidArgumentException('Select a student for the student ledger.');if($student)schoolRecord($db,'students',$student,$school);
        $where='j.school_id=? AND j.posting_date>=? AND j.posting_date<=?';$params=[$school,$from,$to];if($type==='cash'||$type==='bank'){$where.=' AND a.cash_bank_kind=?';$params[]=$type;}if($type==='student'){$where.=" AND l.student_id=? AND a.control_key IN ('receivable','advance')";$params[]=$student;}
        $headers=['Date AD','Date BS','Journal','Account','Description','Debit NPR','Credit NPR'];$numeric=[5,6];$dr=0;$cr=0;
        foreach($ac->rows('SELECT j.*,l.debit_minor,l.credit_minor,a.name account_name FROM ac_journal_lines l JOIN ac_journals j ON j.id=l.journal_id JOIN ac_accounts a ON a.id=l.account_id WHERE '.$where.' ORDER BY j.posting_date,j.id,l.id',$params) as $r){$d=(int)$r['debit_minor'];$c=(int)$r['credit_minor'];$rows[]=[$r['posting_date'],schoolAdToBs($r['posting_date']),$r['number'],$r['account_name'],$r['description'],acAmount($d),acAmount($c)];$dr+=$d;$cr+=$c;}$rows[]=['','','','','Total',acAmount($dr),acAmount($cr)];
    }elseif(in_array($type,['collection','class_collection','category'],true)){
        $where="p.school_id=? AND p.status='posted' AND p.payment_date>=? AND p.payment_date<=?";$params=[$school,$from,$to];foreach(['student_id'=>$student,'method_id'=>$method,'received_by'=>$cashier] as $k=>$v)if($v){$where.=" AND p.$k=?";$params[]=$v;}
        if($type==='collection'){$headers=['Date AD','Date BS','Receipt','Customer','Method','Cashier','Received NPR','Allocated NPR','Advance NPR'];$numeric=[6,7,8];$total=0;foreach($ac->rows('SELECT p.*,m.name method,u.full_name cashier FROM ac_payments p JOIN ac_methods m ON m.id=p.method_id LEFT JOIN users u ON u.id=p.received_by WHERE '.$where.' ORDER BY p.payment_date,p.id',$params) as $p){$allocated=0;foreach($ac->rows('SELECT a.*,i.class_id,i.academic_year_id FROM ac_allocations a JOIN ac_invoices i ON i.id=a.invoice_id WHERE a.payment_id=?',[$p['id']]) as $a)if((!$class||$a['class_id']==$class)&&(!$year||$a['academic_year_id']==$year))$allocated+=(int)$a['amount_minor'];if(($class||$year)&&!$allocated)continue;$received=$class||$year?$allocated:(int)$p['amount_minor'];$rows[]=[$p['payment_date'],schoolAdToBs($p['payment_date']),$p['number'],$p['customer_name'],$p['method'],$p['cashier'],acAmount($received),acAmount($allocated),acAmount($class||$year?0:$received-$allocated)];$total+=$received;}$rows[]=['','','','','','Total',acAmount($total),'',''];}
        else{$headers=[$type==='category'?'Fee category':'Class','Allocated collection NPR'];$numeric=[1];$groups=[];foreach($ac->rows('SELECT a.*,i.class_id,i.academic_year_id,i.total_minor FROM ac_allocations a JOIN ac_payments p ON p.id=a.payment_id JOIN ac_invoices i ON i.id=a.invoice_id WHERE '.$where,$params) as $a){if(($class&&$a['class_id']!=$class)||($year&&$a['academic_year_id']!=$year))continue;if($type==='class_collection'){$c=$a['class_id']?schoolRecord($db,'classes',(int)$a['class_id'],$school):['name'=>'External customer'];$groups[$c['name']]=($groups[$c['name']]??0)+(int)$a['amount_minor'];}else{$lineRows=$ac->rows('SELECT l.*,c.name category FROM ac_invoice_items l LEFT JOIN ac_categories c ON c.id=l.category_id WHERE l.invoice_id=? ORDER BY l.id',[$a['invoice_id']]);$remaining=(int)$a['amount_minor'];$weight=(int)$a['total_minor'];foreach($lineRows as $l){$portion=$weight>0?acMulDiv($remaining,(int)$l['total_minor'],$weight):0;$remaining-=$portion;$weight-=(int)$l['total_minor'];$name=$l['category']?:'Custom / uncategorized';$groups[$name]=($groups[$name]??0)+$portion;}if(!$lineRows)$groups['Opening due']=($groups['Opening due']??0)+(int)$a['amount_minor'];}}$total=0;foreach($groups as $name=>$amount){$rows[]=[$name,acAmount($amount)];$total+=$amount;}$rows[]=['Total',acAmount($total)];}
    }elseif($type==='dues'){
        $headers=['Invoice','Customer','Class','Due date AD','Due date BS','Overdue days','Aging','Outstanding NPR'];$numeric=[5,7];$total=0;
        foreach($ac->rows("SELECT * FROM ac_invoices WHERE school_id=? AND status='issued' ORDER BY due_date,id",[$school]) as $i){if(($student&&$i['student_id']!=$student)||($class&&$i['class_id']!=$class)||($year&&$i['academic_year_id']!=$year))continue;$balance=$ac->invoiceBalance((int)$i['id']);if($balance<=0)continue;$days=max(0,(int)(new DateTimeImmutable($i['due_date']))->diff(new DateTimeImmutable($to))->format('%r%a'));$aging=$days===0?'Not yet due':($days<=30?'1–30':($days<=60?'31–60':($days<=90?'61–90':'90+')));$c=$i['class_id']?schoolRecord($db,'classes',(int)$i['class_id'],$school):[];$rows[]=[$i['number'],$i['customer_name'],$c['name']??'', $i['due_date'],schoolAdToBs($i['due_date']),$days,$aging,acAmount($balance)];$total+=$balance;}$rows[]=['','','','','','','Total',acAmount($total)];
    }elseif($type==='expenses'){$headers=['Expense','Date AD','Date BS','Title','Payee','Status','Amount NPR'];$numeric=[6];$total=0;foreach($ac->rows('SELECT * FROM ac_expenses WHERE school_id=? AND expense_date>=? AND expense_date<=? ORDER BY expense_date,id',[$school,$from,$to]) as $e){$rows[]=[$e['number'],$e['expense_date'],schoolAdToBs($e['expense_date']),$e['title'],$e['payee'],$e['status'],acAmount((int)$e['amount_minor'])];if(in_array($e['status'],['approved','paid'],true))$total+=(int)$e['amount_minor'];}$rows[]=['','','','','','Approved / paid total',acAmount($total)];}
    else{$r=$ac->reconcile();$headers=['Control','General ledger NPR','Subledger NPR','Difference NPR'];$numeric=[1,2,3];$rows=[['Accounts receivable',acAmount($r['receivable_gl']),acAmount($r['receivable_subledger']),acAmount($r['receivable_gl']-$r['receivable_subledger'])],['Student advance',acAmount($r['advance_gl']),acAmount($r['advance_subledger']),acAmount($r['advance_gl']-$r['advance_subledger'])],['Unbalanced journals',(string)$r['unbalanced_journals'],'0',(string)$r['unbalanced_journals']]];}
}catch(InvalidArgumentException $e){$error=$e->getMessage();}
if(!$error&&isset($_GET['export'])){
    require_once __DIR__.'/../../includes/xlsx_helper.php';$format=$_GET['export'];if(!in_array($format,['xlsx','csv'],true))denySchoolRequest('Choose XLSX or CSV export.',422);
    $safeRows=array_map(fn($row)=>array_map(fn($v)=>is_string($v)&&preg_match('/^[=+@\t\r]|^-(?!\d+(?:\.\d+)?$)/',$v)?"'".$v:$v,$row),$rows);
    header('Content-Disposition: attachment; filename="accounting-'.$type.'.'.$format.'"');header('Content-Type: '.($format==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'text/csv; charset=utf-8'));
    echo $format==='xlsx'?XlsxHelper::generateXlsx($headers,$safeRows,'Financial Report',$numeric):XlsxHelper::generateCsv($headers,$safeRows);exit;
}
ob_start();
?>
<form class="row g-2 mb-3 no-print"><div class="col-md-4"><?php acSelect('type','Report',acChoices($types),$type); ?></div><div class="col-md-4"><?php acInput('from','From',$from,'date'); ?></div><div class="col-md-4"><?php acInput('to','To / aging date',$to,'date'); ?></div><details><summary>Student / class / session / method / cashier filters</summary><?php acStudentPicker($student);acSelect('class_id','Class',$ac->rows('SELECT id,name FROM classes WHERE school_id=? ORDER BY id',[$school]),$class,'id','name',false);acSelect('academic_year_id','Academic year',$ac->rows('SELECT id,year_bs name FROM academic_years WHERE school_id=? ORDER BY id DESC',[$school]),$year,'id','name',false);acSelect('method_id','Payment method',$ac->rows('SELECT id,name FROM ac_methods WHERE school_id=?',[$school]),$method,'id','name',false);acSelect('cashier','Received by',$ac->rows('SELECT id,full_name name FROM users WHERE school_id=?',[$school]),$cashier,'id','name',false); ?></details><div><button class="btn btn-primary">Generate report</button><button class="btn btn-outline-secondary" name="export" value="xlsx">Excel</button><button class="btn btn-outline-secondary" name="export" value="csv">CSV</button><button type="button" class="btn btn-outline-secondary" data-erp-click="accounting-reports-action-0" data-erp-click-args="<?= schoolPageActionArgs("accounting-reports",[]) ?>">Print / Save PDF</button></div></form>
<p class="text-muted">Financial statements use posted journal entries. Collection reports exclude reversed payments; class/category collections show allocated payments, not unallocated advances. Outstanding and reconciliation are current balances; aging uses the selected date.</p>
<div class="card card-body table-responsive"><h4><?= sanitize($types[$type]??'Report') ?></h4><p><?= sanitize(schoolDateLabel($from,'both','ymd')) ?> — <?= sanitize(schoolDateLabel($to,'both','ymd')) ?></p><table class="table ac-table"><thead><tr><?php foreach($headers as $h): ?><th><?= sanitize($h) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($r as $v): ?><td><?= sanitize((string)$v) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="<?= max(1,count($headers)) ?>">No matching posted records.</td></tr><?php endif; ?></tbody></table></div>
